server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate /etc/nginx/certs/server.crt;
    ssl_certificate_key /etc/nginx/certs/server.key;

    root /var/www;

    # Main branch at /index.html
    location = /index.html {
        alias /var/www/main/index.html;
        add_header Content-Type text/html;
    }

    # Dev branch at /dev/index.html
    location = /dev/index.html {
        alias /var/www/dev/index.html;
        add_header Content-Type text/html;
    }

    # Fallback for / to serve main index
    location / {
        try_files /main/index.html =404;
    }
}

